-- ROCK9086 pass 8: `{% assign X = {{EXPR}} %}` - a {{ }} inside an assign, the class 008 fixed on the View Case page.
-- Generated by gen_011.py from the live prod values (2026-09-25). Fluid rejects it ("A value was expected"); DotLiquid
-- resolves the no-space form, so the bare expression renders the same on both engines (LavaProbe G1-G3, V1/V2).
-- A wide LIKE first suggested 273 workflow rows; the precise scan found 16 rows (the rest were an assign and a later
-- `= {{ }}` in SQL text). Left alone: AttributeValue 121667807 (workflow 639 "Set Today's date"), which packs a whole
-- template inside one assign tag and fails to parse on DotLiquid as well.
-- Same shape as 005-010: guarded REPLACE per row, @DryRun = 1 rolls back, live run is all-or-nothing, backups to
-- dbo._ROCK9086_LavaBackup, rows absent from the target database log -1. Clear the Rock cache afterwards.
SET NOCOUNT ON; SET XACT_ABORT ON; SET QUOTED_IDENTIFIER ON; SET ANSI_NULLS ON;
DECLARE @DryRun bit = 1;
DECLARE @log TABLE (Tbl sysname, Id int, FixRule varchar(40), [Rows] int);
BEGIN TRAN;

IF OBJECT_ID('dbo._ROCK9086_LavaBackup') IS NULL
    CREATE TABLE dbo._ROCK9086_LavaBackup (Tbl sysname NOT NULL, Id int NOT NULL, Col sysname NOT NULL, OldValue nvarchar(max) NULL, BackedUpAt datetime NOT NULL DEFAULT GETDATE());

INSERT dbo._ROCK9086_LavaBackup (Tbl, Id, Col, OldValue) SELECT 'AttributeValue', x.[Id], 'Value', x.[Value] FROM AttributeValue x WHERE x.[Id] IN (116366873, 116367991, 116368557, 119522298, 119691754, 175793854)
  AND NOT EXISTS (SELECT 1 FROM dbo._ROCK9086_LavaBackup b WHERE b.Tbl = 'AttributeValue' AND b.Id = x.[Id] AND b.Col = 'Value');
INSERT dbo._ROCK9086_LavaBackup (Tbl, Id, Col, OldValue) SELECT 'HtmlContent', x.[Id], 'Content', x.[Content] FROM HtmlContent x WHERE x.[Id] IN (10407, 11981, 12833, 12836, 12837, 6564)
  AND NOT EXISTS (SELECT 1 FROM dbo._ROCK9086_LavaBackup b WHERE b.Tbl = 'HtmlContent' AND b.Id = x.[Id] AND b.Col = 'Content');
INSERT dbo._ROCK9086_LavaBackup (Tbl, Id, Col, OldValue) SELECT 'WorkflowActionForm', x.[Id], 'Header', x.[Header] FROM WorkflowActionForm x WHERE x.[Id] IN (537, 554, 558, 562)
  AND NOT EXISTS (SELECT 1 FROM dbo._ROCK9086_LavaBackup b WHERE b.Tbl = 'WorkflowActionForm' AND b.Id = x.[Id] AND b.Col = 'Header');

UPDATE WorkflowActionForm SET [Header] = REPLACE([Header], N'{% assign failflag = {{Workflow | Attribute:''RegExFailureFlag''}} %}', N'{% assign failflag = Workflow | Attribute:''RegExFailureFlag'' %}')
WHERE [Id] = 537
  AND (LEN([Header]) - LEN(REPLACE([Header], N'{% assign failflag = {{Workflow | Attribute:''RegExFailureFlag''}} %}', N''))) / LEN(N'{% assign failflag = {{Workflow | Attribute:''RegExFailureFlag''}} %}') = 1;
INSERT @log VALUES ('WorkflowActionForm', 537, 'mustache-in-assign', @@ROWCOUNT);
